import{_ as t,o as e,c as o,a6 as c}from"./chunks/framework.BrkgobfX.js";const p=JSON.parse('{"title":"配置项速查","description":"按主题分组的常用 config.toml 配置项，列出键名、类型、默认值与作用（基于 Codex CLI v0.167.0）","frontmatter":{"title":"配置项速查","description":"按主题分组的常用 config.toml 配置项，列出键名、类型、默认值与作用（基于 Codex CLI v0.167.0）","source":"https://daiw.org/manual/codex/config-reference"},"headers":[],"relativePath":"manual/agent/codex/config-reference.md","filePath":"manual/agent/codex/config-reference.md"}'),r={name:"manual/agent/codex/config-reference.md"};function a(l,d,i,s,n,_){return e(),o("div",null,[...d[0]||(d[0]=[c('<h1 id="配置项速查" tabindex="-1">配置项速查 <a class="header-anchor" href="#配置项速查" aria-label="Permalink to &quot;配置项速查&quot;">​</a></h1><blockquote><p>按主题分组的常用 config.toml 配置项，列出键名、类型、默认值与作用（基于 Codex CLI v0.167.0）</p></blockquote><p>本页挑出日常高频使用的配置项并按主题分组，键名、取值与默认值以 v0.167.0 源码为准。完整清单（含 MCP、插件、浏览器、遥测等数百项）见官方 <a href="https://learn.chatgpt.com/docs/config-file/config-reference" target="_blank" rel="noreferrer">Configuration Reference</a> 与 <a href="https://developers.openai.com/codex/config-schema.json" target="_blank" rel="noreferrer">JSON Schema</a>；文件位置与优先级见<a href="/Front2Full/manual/agent/codex/configuration">配置文件</a>。</p><p>表中“—”表示默认不设置；<code>a.b</code> 形式的键在文件里写作 <code>[a]</code> 表下的 <code>b</code>。</p><h2 id="模型与推理" tabindex="-1">模型与推理 <a class="header-anchor" href="#模型与推理" aria-label="Permalink to &quot;模型与推理&quot;">​</a></h2><table tabindex="0"><thead><tr><th>键</th><th>类型 / 取值</th><th>默认</th><th>作用</th></tr></thead><tbody><tr><td><code>model</code></td><td>字符串</td><td>模型目录的默认模型</td><td>默认使用的模型</td></tr><tr><td><code>review_model</code></td><td>字符串</td><td>当前会话模型</td><td><code>/review</code> 使用的模型</td></tr><tr><td><code>model_reasoning_effort</code></td><td><code>low</code>、<code>medium</code>、<code>high</code>、<code>xhigh</code>、<code>max</code>、<code>ultra</code> 等</td><td>模型默认</td><td>推理强度，可用档位由模型决定；<code>reasoning_effort_override</code>（v0.163.0 起默认开启）允许请求超出目录预设列表的档位</td></tr><tr><td><code>plan_mode_reasoning_effort</code></td><td>同上</td><td>计划模式预设</td><td>计划模式专用的推理强度</td></tr><tr><td><code>model_reasoning_summary</code></td><td><code>auto</code>、<code>concise</code>、<code>detailed</code>、<code>none</code></td><td>模型默认</td><td>推理摘要的详细程度；本地 TUI 新会话未设置时按 <code>none</code> 请求，TUI 状态行的实时推理摘要（v0.155.0 起）要设成其他值才会出现</td></tr><tr><td><code>model_verbosity</code></td><td><code>low</code>、<code>medium</code>、<code>high</code></td><td>模型默认</td><td>回答详略</td></tr><tr><td><code>model_context_window</code></td><td>整数</td><td>模型默认</td><td>上下文窗口 token 数</td></tr><tr><td><code>model_auto_compact_token_limit</code></td><td>整数</td><td>模型默认</td><td>触发自动压缩的 token 阈值</td></tr><tr><td><code>model_post_turn_compact_threshold_percent</code></td><td>整数 0～100</td><td>—</td><td>一轮结束后，上下文用量达到可用窗口的这个百分比就先压缩；省略或设为 <code>0</code> 表示不启用（v0.156.0 起）</td></tr><tr><td><code>service_tier</code></td><td>字符串</td><td>—</td><td>服务档位，如 <code>fast</code>（即 <code>priority</code>）、<code>ultrafast</code>、<code>flex</code>、<code>default</code></td></tr><tr><td><code>personality</code></td><td><code>none</code>、<code>friendly</code>、<code>pragmatic</code></td><td>—</td><td>已弃用：v0.156.0 起 <code>friendly</code>、<code>pragmatic</code> 不再改变回复风格，<code>/personality</code> 也已移除；<code>none</code> 仍会去掉模型指令里的 Personality 小节</td></tr><tr><td><code>hide_agent_reasoning</code></td><td>布尔</td><td><code>false</code></td><td>隐藏推理事件（TUI 与 <code>codex exec</code>）</td></tr><tr><td><code>show_raw_agent_reasoning</code></td><td>布尔</td><td><code>false</code></td><td>显示模型输出的原始推理内容</td></tr><tr><td><code>model_catalog_json</code></td><td>路径</td><td>—</td><td>启动时加载的自定义模型目录（v0.167.0 起取消了 1 MiB 文件大小上限）</td></tr></tbody></table><h2 id="模型提供方" tabindex="-1">模型提供方 <a class="header-anchor" href="#模型提供方" aria-label="Permalink to &quot;模型提供方&quot;">​</a></h2><table tabindex="0"><thead><tr><th>键</th><th>类型 / 取值</th><th>默认</th><th>作用</th></tr></thead><tbody><tr><td><code>model_provider</code></td><td>字符串</td><td><code>openai</code></td><td>使用哪个提供方（内置支持 <code>openai</code>、<code>amazon-bedrock</code>、<code>gcp</code>、<code>ollama</code>、<code>lmstudio</code> 等）</td></tr><tr><td><code>openai_base_url</code></td><td>字符串</td><td>—</td><td>改写内置 <code>openai</code> 提供方的地址（代理、数据驻留）</td></tr><tr><td><code>oss_provider</code></td><td><code>ollama</code>、<code>lmstudio</code></td><td>—</td><td><code>--oss</code> 的默认本地提供方，未设时交互询问</td></tr><tr><td><code>model_providers.&lt;id&gt;.base_url</code></td><td>字符串</td><td>—</td><td>提供方 API 地址</td></tr><tr><td><code>model_providers.&lt;id&gt;.env_key</code></td><td>字符串</td><td>—</td><td>存放 API Key 的环境变量名</td></tr><tr><td><code>model_providers.&lt;id&gt;.wire_api</code></td><td><code>responses</code></td><td><code>responses</code></td><td>协议，<code>chat</code> 已不再支持</td></tr><tr><td><code>model_providers.&lt;id&gt;.query_params</code></td><td>表</td><td>—</td><td>追加到请求 URL 的查询参数</td></tr><tr><td><code>model_providers.&lt;id&gt;.http_headers</code></td><td>表</td><td>—</td><td>固定请求头；<code>env_http_headers</code> 则从环境变量取值</td></tr><tr><td><code>model_providers.&lt;id&gt;.request_max_retries</code></td><td>整数</td><td><code>4</code></td><td>HTTP 请求重试次数</td></tr><tr><td><code>model_providers.&lt;id&gt;.stream_max_retries</code></td><td>整数</td><td><code>5</code></td><td>流式响应中断后的重连次数</td></tr><tr><td><code>model_providers.&lt;id&gt;.stream_idle_timeout_ms</code></td><td>整数</td><td><code>300000</code></td><td>流式响应空闲超时（毫秒）</td></tr><tr><td><code>model_providers.&lt;id&gt;.requires_openai_auth</code></td><td>布尔</td><td><code>false</code></td><td>使用 OpenAI 登录凭证</td></tr><tr><td><code>model_providers.&lt;id&gt;.auth.command</code></td><td>字符串</td><td>—</td><td>通过外部命令获取 bearer token</td></tr><tr><td><code>model_providers.&lt;id&gt;.model_catalog_url</code></td><td>字符串</td><td>—</td><td>Codex 格式模型目录的完整地址，获取时带上该提供方的认证、请求头与查询参数（v0.156.0 起；v0.167.0 起内置 <code>openai</code> 提供方也允许单独覆盖该项并取消了 1 MiB 大小限制）</td></tr><tr><td><code>model_providers.&lt;id&gt;.capabilities</code></td><td>表（<code>supports_remote_compaction</code>、<code>supports_turn_metadata_header</code>、<code>supports_web_search</code>、<code>supports_image_generation</code>、<code>supports_Parallel_tool_calls</code>）</td><td>依提供方而定</td><td>显式声明自定义提供方支持的传输层能力（v0.165.0 起）</td></tr><tr><td><code>model_providers.&lt;id&gt;.gateway_oauth</code></td><td>表（<code>authorization_url</code>、<code>token_url</code>、<code>client_id</code>、<code>delivery</code>、<code>credentials_store</code> 等）</td><td>—</td><td>提供方网关额外要求的 OAuth 凭据：浏览器登录后按 <code>delivery</code> 放进请求头或 cookie，与主认证一起发送；<code>credentials_store</code> 可选 <code>auto</code>、<code>file</code>、<code>keyring</code>（v0.156.0 起）</td></tr><tr><td><code>model_providers.amazon-bedrock.aws.profile</code></td><td>字符串</td><td>—</td><td>AWS CLI 配置档名，配合 <code>aws.region</code> 使用</td></tr><tr><td><code>model_providers.amazon-bedrock.aws.credential_export</code></td><td>表（<code>command</code>、<code>args</code>、<code>timeout_ms</code>）</td><td>—</td><td>用外部命令导出 Bedrock 签名所需的 AWS 凭据，<code>timeout_ms</code> 默认 <code>30000</code>，不能与 <code>aws.profile</code> 同用（v0.155.0 起）</td></tr><tr><td><code>model_providers.gcp.project_id</code></td><td>字符串</td><td>—</td><td>Google Cloud Vertex AI 项目 ID（也可由 <code>GOOGLE_CLOUD_PROJECT</code> 提供，v0.165.0 起）</td></tr><tr><td><code>model_providers.gcp.location</code></td><td>字符串</td><td><code>global</code></td><td>Vertex AI 区域或 <code>global</code>（也可由 <code>GOOGLE_CLOUD_LOCATION</code> 提供，v0.165.0 起）</td></tr><tr><td><code>model_providers.gcp.credential_file</code></td><td>路径</td><td>—</td><td>显式指定 ADC 凭据 JSON 文件路径（也可由 <code>GOOGLE_APPLICATION_CREDENTIALS</code> 提供，v0.165.0 起）</td></tr></tbody></table><h2 id="审批与沙箱" tabindex="-1">审批与沙箱 <a class="header-anchor" href="#审批与沙箱" aria-label="Permalink to &quot;审批与沙箱&quot;">​</a></h2><table tabindex="0"><thead><tr><th>键</th><th>类型 / 取值</th><th>默认</th><th>作用</th></tr></thead><tbody><tr><td><code>approval_policy</code></td><td><code>on-request</code>、<code>never</code>、<code>{ granular = { ... } }</code></td><td><code>on-request</code></td><td>何时暂停请求审批；<code>untrusted</code> 已不支持</td></tr><tr><td><code>approval_policy.granular.*</code></td><td>布尔</td><td>—</td><td><code>sandbox_approval</code>、<code>rules</code>、<code>mcp_elicitations</code>、<code>request_permissions</code>、<code>skill_approval</code>，为 <code>false</code> 的类别自动拒绝</td></tr><tr><td><code>approvals_reviewer</code></td><td><code>user</code>、<code>auto_review</code></td><td><code>user</code></td><td>审批请求交给谁审</td></tr><tr><td><code>auto_review.policy</code></td><td>字符串</td><td>—</td><td>自动审查的本地策略，托管的 <code>guardian_policy_config</code> 优先</td></tr><tr><td><code>auto_review.extra_policy</code></td><td>字符串</td><td>—</td><td>追加给自动审查的策略文本，托管的 <code>guardian_extra_policy</code> 优先（v0.157.0 起）</td></tr><tr><td><code>sandbox_mode</code></td><td><code>read-only</code>、<code>workspace-write</code>、<code>danger-full-access</code></td><td>见下方说明</td><td>执行命令时的沙箱模式</td></tr><tr><td><code>sandbox_workspace_write.writable_roots</code></td><td>路径数组</td><td><code>[]</code></td><td>额外的可写目录</td></tr><tr><td><code>sandbox_workspace_write.network_access</code></td><td>布尔</td><td><code>false</code></td><td>允许沙箱内命令联网</td></tr><tr><td><code>sandbox_workspace_write.exclude_tmpdir_env_var</code></td><td>布尔</td><td><code>false</code></td><td>不把 <code>$TMPDIR</code> 视为可写</td></tr><tr><td><code>sandbox_workspace_write.exclude_slash_tmp</code></td><td>布尔</td><td><code>false</code></td><td>不把 <code>/tmp</code> 视为可写</td></tr><tr><td><code>default_permissions</code></td><td>字符串</td><td>—</td><td>默认权限配置档（beta），如 <code>:workspace</code></td></tr><tr><td><code>permissions.&lt;name&gt;.*</code></td><td>表</td><td>—</td><td>自定义权限配置档，不可与 <code>sandbox_mode</code> 混用</td></tr><tr><td><code>allow_login_shell</code></td><td>布尔</td><td><code>true</code></td><td>是否允许 shell 工具使用登录 shell</td></tr><tr><td><code>projects.&lt;path&gt;.trust_level</code></td><td><code>trusted</code>、<code>untrusted</code></td><td>—</td><td>项目信任状态</td></tr><tr><td><code>windows.sandbox</code></td><td><code>elevated</code>、<code>unelevated</code>、<code>mxc</code></td><td>—</td><td>原生 Windows 沙箱实现；<code>mxc</code> 使用微软的 MXC 容器，需要系统支持（v0.156.0 起）</td></tr><tr><td><code>web_search</code></td><td><code>disabled</code>、<code>cached</code>、<code>indexed</code>、<code>live</code></td><td><code>cached</code></td><td>网页搜索模式，完全访问时默认为 <code>live</code></td></tr></tbody></table><p><code>sandbox_mode</code> 未设置时：已有信任决定（<code>trusted</code> 或 <code>untrusted</code>）的目录默认 <code>workspace-write</code>，其余目录默认 <code>read-only</code>；原生 Windows 未配置沙箱时，<code>workspace-write</code> 会降为 <code>read-only</code>。原来的 <code>windows.sandbox_private_desktop</code> 已在 v0.156.0 移除，elevated 与 unelevated 沙箱一律在私有桌面上运行。</p><h2 id="shell-与命令执行" tabindex="-1">Shell 与命令执行 <a class="header-anchor" href="#shell-与命令执行" aria-label="Permalink to &quot;Shell 与命令执行&quot;">​</a></h2><table tabindex="0"><thead><tr><th>键</th><th>类型 / 取值</th><th>默认</th><th>作用</th></tr></thead><tbody><tr><td><code>shell_environment_policy.inherit</code></td><td><code>all</code>、<code>core</code>、<code>none</code></td><td><code>all</code></td><td>子进程环境变量的初始集合</td></tr><tr><td><code>shell_environment_policy.ignore_default_excludes</code></td><td>布尔</td><td><code>true</code></td><td>为 <code>true</code> 时不自动剔除名含 <code>KEY</code>、<code>SECRET</code>、<code>TOKEN</code> 的变量</td></tr><tr><td><code>shell_environment_policy.set</code></td><td>表</td><td>—</td><td>强制设置的变量</td></tr><tr><td><code>shell_environment_policy.filters</code></td><td>表（<code>include</code> / <code>exclude</code>）</td><td>—</td><td>按模式过滤变量，不区分大小写</td></tr><tr><td><code>shell_environment_policy.exclude</code></td><td>数组</td><td>—</td><td>旧写法（另有 <code>include_only</code>），不能与 <code>filters</code> 同层混用</td></tr><tr><td><code>shell_environment_policy.experimental_use_profile</code></td><td>布尔</td><td><code>false</code></td><td>用用户的 shell profile 启动子进程</td></tr><tr><td><code>background_terminal_max_timeout</code></td><td>整数（毫秒）</td><td><code>300000</code></td><td>轮询后台终端输出的等待时间上限</td></tr><tr><td><code>tool_output_token_limit</code></td><td>整数</td><td>—</td><td>单个工具输出存入历史的 token 预算</td></tr></tbody></table><h2 id="项目指令" tabindex="-1">项目指令 <a class="header-anchor" href="#项目指令" aria-label="Permalink to &quot;项目指令&quot;">​</a></h2><table tabindex="0"><thead><tr><th>键</th><th>类型 / 取值</th><th>默认</th><th>作用</th></tr></thead><tbody><tr><td><code>project_doc_max_bytes</code></td><td>整数</td><td><code>32768</code></td><td>项目级 <code>AGENTS.md</code> 合计读取上限（字节）</td></tr><tr><td><code>project_doc_fallback_filenames</code></td><td>字符串数组</td><td><code>[]</code></td><td><code>AGENTS.md</code> 缺失时尝试的备用文件名</td></tr><tr><td><code>project_root_markers</code></td><td>字符串数组</td><td><code>[&quot;.git&quot;]</code></td><td>判定项目根的标记，<code>[]</code> 表示只看当前目录；写在项目配置里不影响查找</td></tr><tr><td><code>developer_instructions</code></td><td>字符串</td><td>—</td><td>额外注入的开发者指令</td></tr><tr><td><code>model_instructions_file</code></td><td>路径</td><td>—</td><td>替换内置模型指令（官方不建议）</td></tr><tr><td><code>compact_prompt</code></td><td>字符串</td><td>—</td><td>自定义历史压缩提示词；只用于本地压缩，OpenAI、Azure、Amazon Bedrock 等走服务端压缩的提供方不使用它</td></tr></tbody></table><h2 id="通知与界面" tabindex="-1">通知与界面 <a class="header-anchor" href="#通知与界面" aria-label="Permalink to &quot;通知与界面&quot;">​</a></h2><table tabindex="0"><thead><tr><th>键</th><th>类型 / 取值</th><th>默认</th><th>作用</th></tr></thead><tbody><tr><td><code>notify</code></td><td>字符串数组</td><td>—</td><td>回合结束时调用的外部程序</td></tr><tr><td><code>tui.notifications</code></td><td>布尔或字符串数组</td><td><code>true</code></td><td>开关 TUI 通知，或只保留指定事件</td></tr><tr><td><code>tui.notification_method</code></td><td><code>auto</code>、<code>osc9</code>、<code>bel</code></td><td><code>auto</code></td><td>终端通知方式</td></tr><tr><td><code>tui.notification_condition</code></td><td><code>unfocused</code>、<code>always</code></td><td><code>unfocused</code></td><td>仅在终端失焦时通知，还是始终通知</td></tr><tr><td><code>tui.animations</code></td><td>布尔</td><td><code>true</code></td><td>动画总开关；v0.156.0 起，首次启动检测到屏幕阅读器、而你又没设置过这一项时，会写入 <code>false</code>，系统开启“减少动态效果”时也不播放动画</td></tr><tr><td><code>tui.effects.&lt;效果&gt;</code></td><td>布尔</td><td><code>true</code></td><td>分别开关 <code>starfield</code>、<code>shimmer</code>、<code>welcome</code>、<code>effort</code>、<code>progress</code>、<code>title</code> 六种效果，受 <code>tui.animations</code> 约束；v0.156.0 起取代 <code>tui.whimsy</code>。v0.158.0 起旧键 <code>tui.whimsy</code> 作为 <code>tui.effects.starfield</code> 的别名重新生效，同一文件里两者都写时以 <code>tui.effects.starfield</code> 为准</td></tr><tr><td><code>tui.alternate_screen</code></td><td><code>auto</code>、<code>always</code>、<code>never</code></td><td><code>auto</code></td><td>是否使用终端备用屏幕；v0.157.0 起，<code>auto</code> 在通过 SSH 使用 macOS Terminal.app 时改用内联模式</td></tr><tr><td><code>tui.fullscreen_transcript</code></td><td>布尔</td><td><code>true</code></td><td>全屏对话记录，由 Codex 接管滚动、选择与搜索；v0.156.0 新增时默认 <code>false</code>，v0.157.0 起默认 <code>true</code>。不使用备用屏幕时不生效，可用 <code>/tui</code> 切换</td></tr><tr><td><code>tui.mouse_scroll_speed</code></td><td>浮点数</td><td><code>1.0</code></td><td>调整全屏模式下鼠标滚轮或触控板滚动的速度倍率（v0.165.0 起）</td></tr><tr><td><code>tui.copy_on_select</code></td><td><code>auto</code>、<code>always</code>、<code>never</code></td><td><code>auto</code></td><td>在 Codex 接管的对话记录或输入框（v0.164.0 起扩展到输入框）中用鼠标选中文字、松开鼠标时是否自动复制；<code>auto</code> 在已知会自行转发复制快捷键的终端（Ghostty 1.2 及以上、macOS 上的 Kitty、Windows Terminal、Windows 上的 VS Code）里不自动复制，其他终端以及 tmux、Zellij 里照常复制（v0.158.0 起）</td></tr><tr><td><code>tui.copy_on_select_clear_selection</code></td><td>布尔</td><td><code>false</code></td><td>自动复制选中文本后是否立即清除选区高亮</td></tr><tr><td><code>tui.right_click_paste</code></td><td><code>auto</code>、<code>on</code>、<code>off</code></td><td><code>auto</code></td><td>全屏模式下没有选中文字时，右键把剪贴板文本粘贴进输入框；<code>auto</code> 只在 Windows、WSL、Linux 上启用，<code>on</code> 连 macOS 也启用，SSH 会话和 VS Code 终端里一律不启用（v0.158.0 起）</td></tr><tr><td><code>tui.rendering.&lt;类型&gt;</code></td><td>布尔</td><td><code>true</code></td><td>分别开关 <code>mermaid</code>（图表）、<code>math</code>（公式）、<code>tables</code>（表格）与 <code>lists</code>（列表符号，v0.157.0 起）的渲染，关闭后显示原文（v0.156.0 起）</td></tr><tr><td><code>tui.show_tooltips</code></td><td>布尔</td><td><code>true</code></td><td>启动时的使用提示；v0.158.0 起全屏对话记录不再在开头显示，改为在回合运行超过 30 秒时或回合结束后偶尔显示一条，同样由它开关</td></tr><tr><td><code>tui.show_server_version_notice</code></td><td>布尔</td><td><code>true</code></td><td>连接的 app server 与 CLI 版本不同时显示提示，不影响兼容性报错（v0.155.0 起；v0.156.0 起预发布版与本地构建也会提示）</td></tr><tr><td><code>tui.theme</code></td><td>字符串</td><td>自动</td><td>语法高亮主题；v0.156.0 起内置 <code>ada</code>、<code>babbage</code>、<code>curie</code>、<code>cushman</code>、<code>dali</code>、<code>davinci</code> 等主题</td></tr><tr><td><code>tui.status_line</code></td><td>字符串数组</td><td><code>model-with-reasoning</code>、<code>current-dir</code>、<code>thread-name</code></td><td>状态栏显示项；v0.166.0 起新增 <code>profile</code> 与 <code>provider</code> 展示项</td></tr><tr><td><code>tui.terminal_title</code></td><td>字符串数组</td><td><code>activity</code>、<code>thread-name</code>、<code>project-name</code></td><td>终端标题显示项</td></tr><tr><td><code>tui.vim_mode_default</code></td><td>布尔</td><td><code>false</code></td><td>输入框默认进入 Vim 模式</td></tr><tr><td><code>tui.raw_output_mode</code></td><td>布尔</td><td><code>false</code></td><td>以便于复制的原始回滚模式启动</td></tr><tr><td><code>tui.presets.&lt;0..9&gt;</code></td><td>表（<code>input</code>、<code>label</code>）</td><td>—</td><td>数字键快捷预设（v0.164.0 起），用 <code>/presets</code> 或 <code>Ctrl+X 0..9</code> 触发；<code>input</code> 长度上限 8000 字节且不可用 <code>!</code> 开头</td></tr><tr><td><code>tui.keymap.&lt;context&gt;.&lt;action&gt;</code></td><td>字符串或数组</td><td>—</td><td>自定义快捷键，空数组表示解绑。支持 <code>Command</code> / <code>Super</code> 修饰键与双键序列（如默认的 <code>Ctrl+X</code> 前缀键，v0.163.0 起）；v0.167.0 起支持 <code>chat.toggle_voice_mute</code>（默认 <code>f9</code>）</td></tr><tr><td><code>realtime.voice</code></td><td>字符串</td><td>服务端默认</td><td>语音对话使用的声音，如 <code>marin</code>、<code>cedar</code>；<code>/voice settings</code> 会写入它（v0.156.0 起）</td></tr><tr><td><code>file_opener</code></td><td><code>vscode</code>、<code>vscode-insiders</code>、<code>windsurf</code>、<code>cursor</code>、<code>none</code></td><td><code>vscode</code></td><td>文件引用链接使用的 URI 方案</td></tr><tr><td><code>check_for_update_on_startup</code></td><td>布尔</td><td><code>true</code></td><td>启动时检查更新</td></tr></tbody></table><h2 id="历史、日志与凭证" tabindex="-1">历史、日志与凭证 <a class="header-anchor" href="#历史、日志与凭证" aria-label="Permalink to &quot;历史、日志与凭证&quot;">​</a></h2><table tabindex="0"><thead><tr><th>键</th><th>类型 / 取值</th><th>默认</th><th>作用</th></tr></thead><tbody><tr><td><code>history.persistence</code></td><td><code>save-all</code>、<code>none</code></td><td><code>save-all</code></td><td>是否写入 <code>history.jsonl</code></td></tr><tr><td><code>history.max_bytes</code></td><td>整数</td><td>—</td><td>历史文件大小上限，超出时丢弃较早记录</td></tr><tr><td><code>log_dir</code></td><td>路径</td><td><code>$CODEX_HOME/log</code></td><td>日志目录，显式设置时额外写 <code>codex-tui.log</code></td></tr><tr><td><code>sqlite_home</code></td><td>路径</td><td><code>CODEX_SQLITE_HOME</code> 或 <code>CODEX_HOME</code></td><td>SQLite 状态库位置</td></tr><tr><td><code>cli_auth_credentials_store</code></td><td><code>file</code>、<code>keyring</code>、<code>auto</code>、<code>ephemeral</code></td><td><code>file</code></td><td>CLI 登录凭证存放方式</td></tr><tr><td><code>mcp_oauth_credentials_store</code></td><td><code>auto</code>、<code>file</code>、<code>keyring</code></td><td><code>auto</code></td><td>MCP OAuth 凭证存放方式</td></tr><tr><td><code>forced_login_method</code></td><td><code>chatgpt</code>、<code>api</code></td><td>—</td><td>限定登录方式</td></tr><tr><td><code>analytics.enabled</code></td><td>布尔</td><td><code>true</code></td><td>匿名使用与健康数据上报</td></tr><tr><td><code>feedback.enabled</code></td><td>布尔</td><td><code>true</code></td><td>是否允许 <code>/feedback</code></td></tr></tbody></table><h2 id="功能开关" tabindex="-1">功能开关 <a class="header-anchor" href="#功能开关" aria-label="Permalink to &quot;功能开关&quot;">​</a></h2><p><code>[features]</code> 表中的常用键，<code>codex features list</code> 可列出全部：</p><table tabindex="0"><thead><tr><th>键</th><th>默认</th><th>成熟度</th><th>作用</th></tr></thead><tbody><tr><td><code>hooks</code></td><td><code>true</code></td><td>稳定</td><td>生命周期 hooks</td></tr><tr><td><code>multi_agent</code></td><td><code>true</code></td><td>稳定</td><td>子代理协作工具</td></tr><tr><td><code>multi_agent_v2</code></td><td><code>false</code></td><td>稳定</td><td>路径寻址（<code>/root/...</code>）的多代理协作工具集（v0.161.0 起支持 Amazon Bedrock）</td></tr><tr><td><code>goals</code></td><td><code>true</code></td><td>稳定</td><td>持久化目标与自动续跑</td></tr><tr><td><code>fast_mode</code></td><td><code>true</code></td><td>稳定</td><td>Fast 服务档位选择</td></tr><tr><td><code>ultrafast_mode</code></td><td><code>true</code></td><td>稳定</td><td>Ultrafast 服务档位选择</td></tr><tr><td><code>reasoning_effort_override</code></td><td><code>true</code></td><td>稳定</td><td>允许请求超出模型目录预设档位列表的推理强度（v0.163.0 起默认开启）</td></tr><tr><td><code>api_key_model_discovery</code></td><td><code>true</code></td><td>稳定</td><td>使用 API Key 登录时从 <code>/v1/models</code> 动态发现可用模型（v0.163.0 起默认开启）</td></tr><tr><td><code>cli_daybreak</code></td><td><code>true</code></td><td>稳定</td><td>在 TUI 中启用 <code>/daybreak</code> 命令（v0.163.0 起默认开启）</td></tr><tr><td><code>bedrock_setup_wizard</code></td><td><code>true</code></td><td>稳定</td><td>登录流程中展示 Amazon Bedrock 配置向导（v0.164.0 起默认开启）</td></tr><tr><td><code>gcp_setup_wizard</code></td><td><code>false</code></td><td>稳定</td><td>登录流程中展示 Google Cloud Vertex AI 配置向导（v0.167.0 起）</td></tr><tr><td><code>apps</code></td><td><code>true</code></td><td>稳定</td><td>App（连接器）集成</td></tr><tr><td><code>plugins</code></td><td><code>true</code></td><td>稳定</td><td>插件</td></tr><tr><td><code>shell_snapshot</code></td><td><code>true</code></td><td>稳定</td><td>快照 shell 环境以加速重复命令</td></tr><tr><td><code>memories</code></td><td><code>false</code></td><td>稳定</td><td>记忆功能</td></tr><tr><td><code>daemon_auto_start</code></td><td><code>true</code></td><td>稳定</td><td>交互式启动时自动拉起共享的后台服务（v0.157.0 起默认开启）</td></tr><tr><td><code>system_proxy_fallback</code></td><td><code>true</code></td><td>稳定</td><td>登录与启动阶段的请求直连失败时，改走系统代理重试（v0.156.0 起）</td></tr><tr><td><code>write_stdin_approval</code></td><td><code>true</code></td><td>稳定</td><td>模型向已在运行的终端写入输入时，若该终端是在沙箱外启动的、带着额外授予的权限，或沙箱设置已与当前权限不一致，要先经过审批（v0.158.0 起默认开启）</td></tr><tr><td><code>network_proxy</code></td><td><code>false</code></td><td>实验</td><td>按域名策略约束已联网的沙箱命令</td></tr><tr><td><code>respect_system_proxy</code></td><td><code>false</code></td><td>实验</td><td>尊重系统代理配置（v0.167.0 起）</td></tr><tr><td><code>prevent_idle_sleep</code></td><td><code>false</code></td><td>实验</td><td>运行期间阻止系统休眠</td></tr><tr><td><code>analytics_plan_history</code></td><td><code>false</code></td><td>实验</td><td>在用量分析面板里预览个人套餐的五小时与每周额度历史（v0.156.0 起）</td></tr><tr><td><code>login_shell_package_path</code></td><td><code>false</code></td><td>实验</td><td>在登录 shell 中注入捆绑工具路径</td></tr></tbody></table><p>多个旧功能开关已因能力固化而退役（配置里残留时会被忽略并在必要时给出清理提示）：<code>personality</code>（v0.156.0）、<code>guardianv2.thread_context</code>（v0.158.0，自动审查始终使用线程上下文）、<code>apply_patch_preserve_line_endings</code>（v0.162.0，<code>apply_patch</code> 默认保留 CRLF）、<code>shell_zsh_fork</code> 与 <code>unified_exec_zsh_fork</code>（v0.163.0，改用标准 shell 执行器）、<code>worktrees</code>（v0.165.0，Git worktree 支持常驻开启）、<code>realtime_conversation</code>（v0.166.0，包含语音运行时的构建常驻开启）、<code>transcript_v2</code>（请改用 <code>tui.fullscreen_transcript</code>）以及 <code>web_search_cached</code> / <code>web_search_request</code>（请改用顶层 <code>web_search</code>）。</p><h2 id="mcp-服务器-摘要" tabindex="-1">MCP 服务器（摘要） <a class="header-anchor" href="#mcp-服务器-摘要" aria-label="Permalink to &quot;MCP 服务器（摘要）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>键</th><th>类型 / 取值</th><th>默认</th><th>作用</th></tr></thead><tbody><tr><td><code>mcp_servers.&lt;id&gt;.command</code></td><td>字符串</td><td>—</td><td>stdio 服务器的启动命令（配合 <code>args</code>、<code>env</code>、<code>cwd</code>）</td></tr><tr><td><code>mcp_servers.&lt;id&gt;.url</code></td><td>字符串</td><td>—</td><td>可流式 HTTP 服务器地址</td></tr><tr><td><code>mcp_servers.&lt;id&gt;.bearer_token_env_var</code></td><td>字符串</td><td>—</td><td>从环境变量读取 bearer token</td></tr><tr><td><code>mcp_servers.&lt;id&gt;.enabled</code></td><td>布尔</td><td>—</td><td>设为 <code>false</code> 可停用而不删除配置</td></tr><tr><td><code>mcp_servers.&lt;id&gt;.required</code></td><td>布尔</td><td>—</td><td>为 <code>true</code> 时初始化失败会让启动失败</td></tr><tr><td><code>mcp_servers.&lt;id&gt;.startup_timeout_sec</code></td><td>数字</td><td><code>30</code></td><td>启动超时（秒）；官方文档写作 <code>10</code></td></tr><tr><td><code>mcp_servers.&lt;id&gt;.startup_readiness</code></td><td><code>connection</code>、<code>catalog</code></td><td><code>connection</code></td><td>启动时是否必须等实时连接就绪；设为 <code>catalog</code> 时可先用有效的缓存工具清单把工具提供给模型，真正调用工具仍需实时连接。与 <code>required = true</code> 同用时，有效的缓存也算启动成功，连接失败要到调用工具时才报错（v0.158.0 起）</td></tr><tr><td><code>mcp_servers.&lt;id&gt;.tool_timeout_sec</code></td><td>数字</td><td><code>300</code></td><td>单次工具调用超时（秒）；官方文档写作 <code>60</code></td></tr><tr><td><code>mcp_servers.&lt;id&gt;.enabled_tools</code></td><td>数组</td><td>—</td><td>工具白名单，另有黑名单 <code>disabled_tools</code></td></tr><tr><td><code>mcp_servers.&lt;id&gt;.tool_input_schema_max_bytes</code></td><td>整数（字节）</td><td><code>5000</code></td><td>单个工具的输入 schema 超过这个大小时逐步压缩（先删参数说明，再删定义等），调大可保留更多参数说明（v0.158.0 起）</td></tr><tr><td><code>mcp_servers.&lt;id&gt;.oauth.client_secret</code></td><td>字符串</td><td>—</td><td>预注册 OAuth 客户端的密钥，换取令牌时使用，必须同时设置 <code>oauth.client_id</code>；也可用 <code>codex mcp add --oauth-client-secret</code> 写入（v0.158.0 起）</td></tr></tbody></table><p>完整字段与用法见 <a href="/Front2Full/manual/agent/codex/mcp">MCP 集成</a>。</p><h2 id="其他" tabindex="-1">其他 <a class="header-anchor" href="#其他" aria-label="Permalink to &quot;其他&quot;">​</a></h2><table tabindex="0"><thead><tr><th>键</th><th>类型 / 取值</th><th>默认</th><th>作用</th></tr></thead><tbody><tr><td><code>agents.max_concurrent_threads_per_session</code></td><td>整数</td><td>由 Codex 决定</td><td>同时打开的子代理线程上限</td></tr><tr><td><code>agents.default_subagent_model</code></td><td>字符串</td><td>—</td><td>子代理默认模型，见<a href="/Front2Full/manual/agent/codex/subagents">子代理</a></td></tr><tr><td><code>plugins.&lt;id&gt;.enabled</code></td><td>布尔</td><td><code>false</code></td><td>启用或停用已安装的插件</td></tr><tr><td><code>plugins.&lt;id&gt;.apps.&lt;connector_id&gt;.*</code></td><td>表</td><td>—</td><td>在插件配置内直接设置关联连接器（App）的启用状态与审批策略（v0.167.0 起）</td></tr><tr><td><code>hooks.&lt;Event&gt;</code></td><td>表数组</td><td>—</td><td>内联 hooks，见 <a href="/Front2Full/manual/agent/codex/hooks">Hooks</a></td></tr><tr><td><code>memories.version</code></td><td><code>v1</code>、<code>v2</code></td><td>新配置档默认 <code>v2</code></td><td>记忆管线版本，<code>v2</code> 的数据单独存放（v0.155.0 起；v0.165.0 起新开启记忆的配置档默认采用 <code>v2</code>）</td></tr><tr><td><code>memories.dual_write</code></td><td>布尔</td><td><code>false</code></td><td>两个版本的记忆同时生成，上下文仍取 <code>memories.version</code> 选中的版本（v0.155.0 起）</td></tr><tr><td><code>otel.exporter</code></td><td><code>none</code>、<code>otlp-http</code>、<code>otlp-grpc</code></td><td><code>none</code></td><td>OpenTelemetry 日志导出</td></tr><tr><td><code>otel.log_user_prompt</code></td><td>布尔</td><td><code>false</code></td><td>导出时是否包含用户提示原文</td></tr><tr><td><code>otel.log_agent_responses</code></td><td>布尔</td><td><code>false</code></td><td>把主代理与子代理的最终回复写入 OTLP 日志，只在 <code>otel.exporter</code> 为 <code>otlp-http</code> 或 <code>otlp-grpc</code> 时生效；内容可能敏感，每条上限为 64 KiB（v0.158.0 起）</td></tr><tr><td><code>otel.log_guardian_assessments</code></td><td>布尔</td><td><code>false</code></td><td>把自动审查完成的评估（含理由）写入 OTLP 日志，生效条件同上，理由上限为 64 KiB（v0.158.0 起）</td></tr></tbody></table><h2 id="requirements-toml-常用键" tabindex="-1">requirements.toml 常用键 <a class="header-anchor" href="#requirements-toml-常用键" aria-label="Permalink to &quot;requirements.toml 常用键&quot;">​</a></h2><p>以下键只在管理员下发的 <code>requirements.toml</code>（或系统级 MDM / Windows 注册表策略）中有意义，用户与项目配置无法越过：</p><table tabindex="0"><thead><tr><th>键</th><th>作用</th></tr></thead><tbody><tr><td><code>allowed_approval_policies</code></td><td>允许的 <code>approval_policy</code>；列入 <code>untrusted</code> 表示允许不信任项目派生出的严格策略</td></tr><tr><td><code>allowed_approvals_reviewers</code></td><td>允许的 <code>approvals_reviewer</code></td></tr><tr><td><code>allowed_sandbox_modes</code></td><td>允许的 <code>sandbox_mode</code></td></tr><tr><td><code>allowed_permission_profiles</code></td><td>允许的权限配置档，未列出的一律禁止</td></tr><tr><td><code>allowed_web_search_modes</code></td><td>允许的 <code>web_search</code> 模式，<code>disabled</code> 始终允许</td></tr><tr><td><code>guardian_policy_config</code></td><td>托管的自动审查策略，优先于本地 <code>auto_review.policy</code></td></tr><tr><td><code>guardian_extra_policy</code></td><td>托管的附加审查策略，优先于本地 <code>auto_review.extra_policy</code>（v0.157.0 起）</td></tr><tr><td><code>model_provider</code>、<code>model_providers</code></td><td>强制选用的提供方，以及整体替换本地同名条目的提供方定义（v0.156.0 起）</td></tr><tr><td><code>features.&lt;name&gt;</code></td><td>锁定某个功能开关的取值</td></tr><tr><td><code>permissions.filesystem.deny_read</code></td><td>跨层级叠加禁止读取的路径或 glob 模式</td></tr><tr><td><code>permissions.network</code></td><td>托管的网络权限约束（域名策略、Unix 套接字等，v0.165.0 起支持直接配置）</td></tr><tr><td><code>network_proxy</code></td><td>托管的网络代理设置（v0.162.0 起）</td></tr><tr><td><code>rules.prefix_rules</code></td><td>托管的命令前缀规则列表，取值可为 <code>prompt</code>、<code>prompt-user</code>（v0.167.0 起，即使开启自动审查也要求真人审批）或 <code>forbidden</code></td></tr><tr><td><code>otel</code></td><td>托管的 OpenTelemetry 遥测导出配置（v0.163.0 起）</td></tr><tr><td><code>windows.allowed_sandbox_implementations</code></td><td>允许的原生 Windows 沙箱实现</td></tr><tr><td><code>models.new_thread.model</code></td><td>新会话的托管默认模型，显式指定模型或推理强度时失效</td></tr></tbody></table>',31)])])}const u=t(r,[["render",a]]);export{p as __pageData,u as default};
